H,W=27,23
G=[[8]*W for _ in range(H)]
frames=[(1,5,2,2),(7,11,4,4),(13,17,3,1),(19,23,1,1)] # start/end rows, color, object count
for r0,r1,col,n in frames:
    for c in range(1,12):
        G[r0][c]=col; G[r1][c]=col
    for r in range(r0+1,r1):
        G[r][1]=G[r][11]=col
    mid=(r0+r1)//2
    for i in range(n):
        G[mid][11-2*n+2*i]=col
print('\n'.join(' '.join(map(str,row)) for row in G))
print([len(row) for row in G])
